using UnityEngine;using UnityEditor;
public static class MakongPresentationInstaller {
 [MenuItem("Editor/Makong/Configure audiovisual presentation")]
 public static string Install(){const string path="Assets/Resources/Combat/MakongPresentation.asset";var p=AssetDatabase.LoadAssetAtPath<CorruptedEncounterPresentationSettings>(path);if(p==null){p=ScriptableObject.CreateInstance<CorruptedEncounterPresentationSettings>();AssetDatabase.CreateAsset(p,path);}p.dialogueMusic=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Corrupted Memories.mp3");p.battleMusic=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Boss Battle Groove.mp3");if(p.dialogueMusic==null||p.battleMusic==null)throw new System.InvalidOperationException("Missing requested music clips");p.light.clip=Resources.Load<AudioClip>("Audio/Temporary/CorruptionLight");p.moderate.clip=Resources.Load<AudioClip>("Audio/Temporary/CorruptionModerate");p.strong.clip=Resources.Load<AudioClip>("Audio/Temporary/CorruptionStrong");EditorUtility.SetDirty(p);
 var settings=MakongSpecialSettings.Current;Undo.RecordObject(settings,"Configure Makong presentation");settings.presentation=p;if(settings.encounterDialogue.Length!=51)throw new System.InvalidOperationException("Review narrative line metadata before installing");settings.encounterDialogue[19].audiovisualCue=DialogueAudiovisualCue.Observed;settings.encounterDialogue[36].audiovisualCue=DialogueAudiovisualCue.Distress;settings.encounterDialogue[41].audiovisualCue=DialogueAudiovisualCue.Quiet;settings.encounterDialogue[42].audiovisualCue=DialogueAudiovisualCue.Quiet;settings.encounterDialogue[50].audiovisualCue=DialogueAudiovisualCue.DramaticCut;EditorUtility.SetDirty(settings);
 foreach(var clip in new[]{p.dialogueMusic,p.battleMusic}){var importer=AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(clip)) as AudioImporter;if(importer!=null){var sample=importer.defaultSampleSettings;sample.loadType=AudioClipLoadType.Streaming;sample.preloadAudioData=false;importer.defaultSampleSettings=sample;importer.loadInBackground=true;importer.SaveAndReimport();}}
 AssetDatabase.SaveAssets();return "Makong music and metadata configured; dialogue words unchanged";}
}
